-- Engelsk batch 2, 5. klasse bånd 3-4: 166 nye MC-spørgsmål (learning_objective='english', bånd 1-4).
-- Del af 1000 nye engelskspørgsmål til 3.-5. klasse. Samme indholds- og metadata-mønster som
-- 20261001000000_english_grade3_5; metadata afledes her af kategorinøglen k:
-- o=ordforråd, h=hverdagsudtryk, g=grammatik, l=læseforståelse. difficulty = bånd.
-- Bånd 1-2: reinforcement/conceptual_bridge. Bånd 3-4: challenge/reframing. All is_active=true.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', CASE WHEN (e->>'b')::int >= 3 THEN 'challenge' ELSE 'reinforcement' END,
                     'insight_type', CASE WHEN (e->>'b')::int >= 3 THEN 'reframing' ELSE 'conceptual_bridge' END,
                     'domain', 'english'),
  'mc_single', (e->>'b')::int, 'auto', true, 'english', (e->>'g')::int, (e->>'b')::int
FROM jsonb_array_elements($$[
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'I have ___ my homework.' (har lavet)","o":["done","did","do","doing"],"a":"done","r":"Efter 'have' bruger man kort tillægsform: have done = har lavet."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'Have you ever ___ a snake?'","o":["saw","see","seeing","seen"],"a":"seen","r":"'Have you ever seen …?' = har du nogensinde set …? 'Seen' er tillægsformen af 'see'."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'She has ___ to Paris three times.'","o":["was","be","been","being"],"a":"been","r":"'Has been to' betyder har været i/på: She has been to Paris."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'We ___ just eaten.'","o":["has","have","are","did"],"a":"have","r":"Med 'we' bruger man 'have': We have just eaten = vi har lige spist."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'Has he finished ___?'","o":["yet","already","ago","since"],"a":"yet","r":"'Yet' bruges i spørgsmål og nægtelser: Has he finished yet? = er han færdig endnu?"},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'I have ___ finished the book. It was great!'","o":["yet","ago","since","just"],"a":"just","r":"'Just' betyder lige: I have just finished = jeg er lige blevet færdig."},
{"g":5,"b":3,"k":"g","q":"Hvad er tillægsformen (3. form) af 'write'?","o":["wrote","writed","written","writing"],"a":"written","r":"Write – wrote – written. 'I have written a letter.'"},
{"g":5,"b":3,"k":"g","q":"Hvad er tillægsformen (3. form) af 'eat'?","o":["ate","eaten","eated","eat"],"a":"eaten","r":"Eat – ate – eaten. 'Have you eaten?'"},
{"g":5,"b":3,"k":"g","q":"Hvad er tillægsformen (3. form) af 'speak'?","o":["spoken","spoke","speaked","speaken"],"a":"spoken","r":"Speak – spoke – spoken."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'While I ___ a shower, the phone rang.'","o":["had","have","am having","was having"],"a":"was having","r":"Noget, der var i gang i datid: was having. Det blev afbrudt af telefonen."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'If it rains, we ___ stay inside.'","o":["would","are","will","did"],"a":"will","r":"Første betingelse: If + nutid, … will: If it rains, we will stay inside."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'If you ___ hard, you will pass the test.'","o":["will study","study","studied","studying"],"a":"study","r":"Efter 'if' bruger man nutid, når det handler om fremtiden: If you study …"},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'I'm tired. I think I ___ go to bed.'","o":["will","am","did","was"],"a":"will","r":"Når man beslutter noget lige nu, bruger man 'will': I think I'll go to bed."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'You ___ bring a coat. It's going to be cold.'","o":["shouldn't","mustn't","can't","should"],"a":"should","r":"'Should' bruges til gode råd: You should bring a coat = du bør tage en frakke med."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'You ___ run near the pool. It's dangerous!'","o":["must","should","mustn't","can"],"a":"mustn't","r":"'Mustn't' betyder må ikke. Det er forbudt."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'You ___ come if you don't want to.' (det er ikke nødvendigt)","o":["mustn't","don't have to","have to","must"],"a":"don't have to","r":"'Don't have to' betyder 'behøver ikke'. 'Mustn't' betyder 'må ikke'."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'When I was five, I ___ swim.' (kunne ikke)","o":["couldn't","can't","don't","wasn't"],"a":"couldn't","r":"Datid af 'can't' er 'couldn't'."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'It's a nice day, ___ it?'","o":["is","doesn't","wasn't","isn't"],"a":"isn't","r":"Et 'question tag' vender sætningen: It is … isn't it? = ikke sandt?"},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'You like pizza, ___ you?'","o":["do","aren't","don't","didn't"],"a":"don't","r":"Positiv sætning får negativt 'tag': You like … don't you?"},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'This bike is ___ expensive as that one.' (lige så)","o":["so","as","than","more"],"a":"as","r":"'As … as' betyder lige så … som: as expensive as."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'My bag is not as heavy ___ yours.'","o":["as","than","like","that"],"a":"as","r":"'Not as … as' betyder ikke så … som."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'I'm looking forward ___ the summer holidays.'","o":["for","at","on","to"],"a":"to","r":"Man siger altid 'look forward to' = glæde sig til."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'She is afraid ___ spiders.'","o":["for","from","of","about"],"a":"of","r":"'Afraid of' = bange for."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'The house ___ built in 1900.'","o":["were","was","is","has"],"a":"was","r":"'Was built' = blev bygget. 'The house' er ental."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'English ___ spoken in many countries.'","o":["is","are","be","has"],"a":"is","r":"'Is spoken' = bliver talt/tales. Passiv form."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'The man ___ car was stolen called the police.'","o":["who","which","who's","whose"],"a":"whose","r":"'Whose' betyder hvis: the man whose car … = manden, hvis bil …"},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'actually'?","o":["aktuelt","aktivt","faktisk","akkurat nu"],"a":"faktisk","r":"Falsk ven! 'Actually' betyder faktisk. 'Aktuel' hedder 'current'."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'chef'?","o":["chef","kok","leder af et firma","direktør"],"a":"kok","r":"Falsk ven! 'Chef' er en kok. En chef (leder) hedder 'boss'."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'smoking' i 'No smoking'?","o":["rygning","smoking (jakkesæt)","smukt","smøring"],"a":"rygning","r":"'Smoking' betyder rygning. 'No smoking' = rygning forbudt. Smokingjakken hedder 'dinner jacket'."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'novel'?","o":["novelle","nyhed","nummer","roman"],"a":"roman","r":"Falsk ven! 'Novel' er en roman. En novelle hedder 'short story'."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'become'?","o":["bekomme","komme","blive","bede om"],"a":"blive","r":"Falsk ven! 'Become' betyder blive: 'I want to become a vet.'"},
{"g":5,"b":3,"k":"o","q":"Hvad betyder det engelske ord 'meaning'?","o":["mening (holdning)","betydning","møde","menneske"],"a":"betydning","r":"'Meaning' betyder betydning: the meaning of a word. En holdning hedder 'opinion'."},
{"g":5,"b":3,"k":"o","q":"Hvad er navneordet af 'decide' (at beslutte)?","o":["decision","decidement","decidness","decider"],"a":"decision","r":"Decide → decision = beslutning."},
{"g":5,"b":3,"k":"o","q":"Hvad er det modsatte af 'possible'?","o":["unpossible","dispossible","nonpossible","impossible"],"a":"impossible","r":"Forstavelsen im- gør ordet negativt: possible → impossible."},
{"g":5,"b":3,"k":"o","q":"Hvad er det modsatte af 'happy' med forstavelse?","o":["dishappy","inhappy","unhappy","nonhappy"],"a":"unhappy","r":"Forstavelsen un- betyder ikke: unhappy = ulykkelig."},
{"g":5,"b":3,"k":"o","q":"Hvad er det modsatte af 'honest'?","o":["unhonest","dishonest","inhonest","nohonest"],"a":"dishonest","r":"'Dishonest' betyder uærlig."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'careless'?","o":["skødesløs","omsorgsfuld","bilfri","billig"],"a":"skødesløs","r":"-less betyder uden: careless = uden omhu, altså skødesløs."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'helpful'?","o":["hjælpeløs","sund","hel","hjælpsom"],"a":"hjælpsom","r":"-ful betyder fuld af: helpful = hjælpsom."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'environment'?","o":["udstyr","underholdning","miljø","regering"],"a":"miljø","r":"'Environment' betyder miljø: 'We must protect the environment.'"},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'pollution'?","o":["befolkning","forurening","politik","pollen"],"a":"forurening","r":"'Pollution' betyder forurening."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'recycle'?","o":["genbruge","cykle igen","reparere","rydde op"],"a":"genbruge","r":"'Recycle' betyder genbruge: 'We recycle bottles and paper.'"},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'government'?","o":["guvernante","gave","kommune","regering"],"a":"regering","r":"'Government' betyder regering."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'experience'?","o":["eksperiment","ekspert","erfaring eller oplevelse","eksamen"],"a":"erfaring eller oplevelse","r":"'Experience' betyder erfaring eller oplevelse."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'opportunity'?","o":["modstander","mulighed","operation","åbning"],"a":"mulighed","r":"'Opportunity' betyder mulighed eller chance."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'It's a piece of cake'?","o":["Det er meget nemt","Det er et stykke kage","Det er lækkert","Det er en lille del"],"a":"Det er meget nemt","r":"Idiom! 'A piece of cake' betyder at noget er meget nemt."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'I'm all ears'?","o":["Jeg har store ører","Jeg hører dårligt","Jeg er træt","Jeg lytter"],"a":"Jeg lytter","r":"Idiom! 'I'm all ears' = jeg er lutter øre — jeg lytter."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'Break a leg!'?","o":["Pas på benet!","Løb hurtigt!","Held og lykke!","God bedring!"],"a":"Held og lykke!","r":"Idiom! 'Break a leg!' siger man til skuespillere før en forestilling — held og lykke!"},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'It's not my cup of tea'?","o":["Det er ikke min kop","Det er ikke lige mig","Jeg drikker ikke te","Det er ikke mit problem"],"a":"Det er ikke lige mig","r":"Idiom! 'Not my cup of tea' = det er ikke noget for mig."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'Once in a blue moon'?","o":["Meget sjældent","Hver måned","Om natten","Når det er fuldmåne"],"a":"Meget sjældent","r":"Idiom! 'Once in a blue moon' = meget sjældent."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'I'm feeling under the weather'?","o":["Jeg står i regnen","Jeg kan lide dårligt vejr","Jeg er glad","Jeg har det lidt skidt"],"a":"Jeg har det lidt skidt","r":"Idiom! 'Under the weather' = lidt syg eller utilpas."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'Let's call it a day'?","o":["Lad os ringe i dag","Lad os kalde det en god dag","Lad os stoppe for i dag","Lad os starte i dag"],"a":"Lad os stoppe for i dag","r":"Idiom! 'Call it a day' = holde fri/stoppe for i dag."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'Keep your fingers crossed for me'?","o":["Hold fingrene væk fra mig","Kryds fingre for mig","Giv mig en hånd","Pas på dine fingre"],"a":"Kryds fingre for mig","r":"Man krydser fingre for at ønske held."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'I don't mind'?","o":["Det er lige meget for mig","Jeg kan ikke huske det","Jeg kan ikke lide det","Jeg tænker ikke"],"a":"Det er lige meget for mig","r":"'I don't mind' = det gør mig ikke noget/det er fint med mig."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Although it was snowing, Ida rode her bike to school.' Hvad gjorde Ida?","o":["Hun gik, fordi det sneede","Hun blev hjemme","Hun tog bussen","Hun cyklede, selvom det sneede"],"a":"Hun cyklede, selvom det sneede","r":"'Although' = selvom. Hun cyklede alligevel."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Max has been playing the piano since he was six. Now he is twelve.' Hvor længe har Max spillet klaver?","o":["tolv år","to år","seks år","atten år"],"a":"seks år","r":"Fra han var seks til nu, hvor han er tolv: 12 − 6 = 6 år."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Sara would rather read a book than watch TV.' Hvad foretrækker Sara?","o":["at se fjernsyn","at læse en bog","begge dele lige meget","ingen af delene"],"a":"at læse en bog","r":"'Would rather … than' = vil hellere … end."},
{"g":5,"b":3,"k":"l","q":"Læs: 'The concert was cancelled because the singer was ill.' Hvad skete der med koncerten?","o":["Den blev aflyst","Den blev udsat en time","Den blev holdt alligevel","Den blev flyttet"],"a":"Den blev aflyst","r":"'Cancelled' betyder aflyst."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Anna couldn't believe her eyes when she saw her old friend at the airport.' Hvordan havde Anna det?","o":["Hun kunne ikke se","Hun var træt","Hun var vred","Hun var meget overrasket"],"a":"Hun var meget overrasket","r":"'Couldn't believe her eyes' = kunne ikke tro sine egne øjne — hun var meget overrasket."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Jake has lost his key, so he can't get into his house.' Hvad er Jakes problem?","o":["Han kan ikke finde sit hus","Han er låst inde","Han kan ikke komme ind i sit hus","Hans hus er solgt"],"a":"Han kan ikke komme ind i sit hus","r":"'Get into' betyder komme ind i."},
{"g":5,"b":3,"k":"l","q":"Læs: 'The trip was supposed to start at 8, but it was delayed by two hours.' Hvornår startede turen?","o":["kl. 8","kl. 10","kl. 6","kl. 12"],"a":"kl. 10","r":"'Delayed by two hours' = forsinket to timer: 8 + 2 = 10."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Unlike her brother, Lily loves maths.' Hvad ved vi om broren?","o":["Han kan ikke lide matematik","Han elsker matematik","Han er god til matematik","Han er lærer"],"a":"Han kan ikke lide matematik","r":"'Unlike' betyder i modsætning til."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Oliver hasn't seen his cousin since last Christmas.' Hvornår så Oliver sidst sin fætter?","o":["i går","i sommer","aldrig","sidste jul"],"a":"sidste jul","r":"'Since last Christmas' = siden sidste jul."},
{"g":5,"b":3,"k":"l","q":"Læs: 'The more you practise, the better you get.' Hvad betyder sætningen?","o":["Man skal øve sig mindre","Det er bedre at hvile","Jo mere man øver sig, jo bedre bliver man","Man bliver aldrig bedre"],"a":"Jo mere man øver sig, jo bedre bliver man","r":"'The more … the better' = jo mere … jo bedre."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Lucy wasn't allowed to go to the party because she hadn't finished her homework.' Hvorfor måtte Lucy ikke gå til festen?","o":["Hun var syg","Hun var ikke færdig med lektierne","Hun var ikke inviteret","Festen var aflyst"],"a":"Hun var ikke færdig med lektierne","r":"'Hadn't finished her homework' = havde ikke lavet sine lektier færdige."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Despite the rain, the football match continued.' Hvad skete der?","o":["Kampen fortsatte trods regnen","Kampen stoppede pga. regn","Det holdt op med at regne","Kampen startede ikke"],"a":"Kampen fortsatte trods regnen","r":"'Despite' betyder trods/på trods af."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Emil is saving up for a new bike. He has saved half of the money already.' Hvor langt er Emil?","o":["Han har alle pengene","Han har ingen penge","Han har købt cyklen","Han mangler halvdelen af pengene"],"a":"Han mangler halvdelen af pengene","r":"'Half of the money' = halvdelen af pengene. Han mangler resten."},
{"g":5,"b":3,"k":"l","q":"Læs: 'The beach was crowded, so we found a quieter place further away.' Hvorfor gik de længere væk?","o":["Det var for koldt","Stranden var lukket","Der var for mange mennesker","Der var for meget tang"],"a":"Der var for mange mennesker","r":"'Crowded' betyder fyldt med mennesker."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Nina usually gets good marks, but this time she failed the test.' Hvad var anderledes denne gang?","o":["Hun fik den bedste karakter","Hun dumpede prøven","Hun var ikke til prøve","Hun snød"],"a":"Hun dumpede prøven","r":"'Failed' betyder dumpede. Normalt (usually) får hun gode karakterer."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Instead of going by car, we decided to cycle to the beach.' Hvordan kom de til stranden?","o":["på cykel","i bil","med bus","til fods"],"a":"på cykel","r":"'Instead of' = i stedet for. 'Cycle' = cykle."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Peter is so good at chess that nobody in his class can beat him.' Hvad betyder det?","o":["Han taber altid","Han slår sine klassekammerater","Han kan ikke spille skak","Ingen i klassen kan slå ham i skak"],"a":"Ingen i klassen kan slå ham i skak","r":"'Beat' betyder her slå (vinde over)."},
{"g":5,"b":3,"k":"l","q":"Læs: 'We ran out of milk, so Dad went to the shop.' Hvorfor gik far i butikken?","o":["Han skulle købe brød","Mælken var sur","De havde ikke mere mælk","Butikken lukkede snart"],"a":"De havde ikke mere mælk","r":"'Ran out of' = løb tør for."},
{"g":5,"b":3,"k":"l","q":"Læs: 'The film was based on a true story.' Hvad betyder det?","o":["Filmen er et eventyr","Filmen handler om noget, der virkelig skete","Filmen er meget lang","Filmen er lavet om til en bog"],"a":"Filmen handler om noget, der virkelig skete","r":"'Based on a true story' = bygget på en sand historie."},
{"g":5,"b":3,"k":"g","q":"Hvad er tillægsformen (3. form) af 'go'?","o":["gone","went","goed","going"],"a":"gone","r":"Go – went – gone. 'She has gone home' = hun er gået hjem."},
{"g":5,"b":3,"k":"g","q":"Hvad er tillægsformen (3. form) af 'take'?","o":["took","taked","tooken","taken"],"a":"taken","r":"Take – took – taken. 'Who has taken my pen?'"},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'I ___ to the cinema yesterday.'","o":["have gone","have been","went","go"],"a":"went","r":"Med et bestemt tidspunkt i fortiden ('yesterday') bruger man datid: I went."},
{"g":5,"b":3,"k":"g","q":"Hvilket ord mangler? 'If I see Tom, I ___ tell him.'","o":["would","will","am","did"],"a":"will","r":"If + nutid → will: If I see Tom, I will tell him."},
{"g":5,"b":3,"k":"o","q":"Hvad er navneordet af 'happy' (glæde/lykke)?","o":["happiness","happyness","happiment","happity"],"a":"happiness","r":"Happy → happiness. Y bliver til i foran -ness."},
{"g":5,"b":3,"k":"o","q":"Hvad er navneordet af 'friend' (venskab)?","o":["friendness","friendhood","friendment","friendship"],"a":"friendship","r":"Friend → friendship = venskab."},
{"g":5,"b":3,"k":"o","q":"Hvad betyder 'kind of' i 'It's kind of cold'?","o":["venlig af","aldrig","lidt/på en måde","meget"],"a":"lidt/på en måde","r":"'Kind of' bruges i talesprog: 'It's kind of cold' = det er lidt koldt."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'Better late than never'?","o":["Bedre at komme for tidligt","Hellere sent end aldrig","Det er for sent nu","Kom aldrig for sent"],"a":"Hellere sent end aldrig","r":"Udtrykket betyder, at det er bedre at gøre noget sent end slet ikke."},
{"g":5,"b":3,"k":"h","q":"Hvad betyder 'It's raining heavily – I'm soaked!'?","o":["Det øsregner – jeg er gennemblødt!","Det regner lidt – jeg er tørstig!","Det er tungt – jeg er træt!","Det har regnet – jeg er glad!"],"a":"Det øsregner – jeg er gennemblødt!","r":"'Soaked' betyder gennemblødt, og 'heavily' betyder kraftigt."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Hardly anyone came to the meeting.' Hvor mange kom?","o":["næsten alle","alle","præcis halvdelen","næsten ingen"],"a":"næsten ingen","r":"'Hardly anyone' betyder næsten ingen."},
{"g":5,"b":3,"k":"l","q":"Læs: 'Tom apologised for being rude.' Hvad gjorde Tom?","o":["Han var uhøflig igen","Han blev vred","Han sagde undskyld for at være uhøflig","Han takkede for hjælpen"],"a":"Han sagde undskyld for at være uhøflig","r":"'Apologise' betyder sige undskyld, og 'rude' betyder uhøflig."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'If I ___ a million pounds, I would buy a horse.'","o":["have","had","will have","would have"],"a":"had","r":"Anden betingelse (noget usandsynligt): If + datid, … would: If I had …"},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'If I were you, I ___ tell the teacher.'","o":["would","will","am","did"],"a":"would","r":"'If I were you' = hvis jeg var dig. Så følger 'would': I would tell …"},
{"g":5,"b":4,"k":"g","q":"Hvad betyder 'If I were you, I would apologise'?","o":["Hvis du var mig, ville du sige undskyld","Jeg sagde undskyld til dig","Du skal ikke sige undskyld","Hvis jeg var dig, ville jeg sige undskyld"],"a":"Hvis jeg var dig, ville jeg sige undskyld","r":"'If I were you' bruges, når man giver et råd."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'I ___ been waiting for an hour!'","o":["am","was","have","did"],"a":"have","r":"'Have been waiting' = har ventet (og venter stadig)."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'How long have you been ___ English?'","o":["learn","learning","learned","learns"],"a":"learning","r":"'Have been + -ing' viser noget, der har stået på længe: How long have you been learning …?"},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'The letter ___ written by my grandmother.'","o":["was","were","has","did"],"a":"was","r":"Passiv i datid: was written = blev skrevet."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'The windows are ___ every week.'","o":["clean","cleaning","cleans","cleaned"],"a":"cleaned","r":"Passiv: are cleaned = bliver gjort rene."},
{"g":5,"b":4,"k":"g","q":"Hvilken sætning er passiv?","o":["The children ate the cake.","The children are eating cake.","The cake was eaten by the children.","The children like cake."],"a":"The cake was eaten by the children.","r":"I passiv er det, der sker med noget, i fokus: The cake was eaten = kagen blev spist."},
{"g":5,"b":4,"k":"g","q":"Tom siger: 'I am tired.' Hvordan genfortæller man det?","o":["Tom said that I am tired.","Tom said that he was tired.","Tom said he is tire.","Tom says that he were tired."],"a":"Tom said that he was tired.","r":"I indirekte tale rykker tiden tilbage: am → was, og 'I' bliver til 'he'."},
{"g":5,"b":4,"k":"g","q":"Anna siger: 'I like dogs.' Hvordan genfortæller man det?","o":["Anna said that she liked dogs.","Anna said that I like dogs.","Anna said she like dogs.","Anna says that she liking dogs."],"a":"Anna said that she liked dogs.","r":"Indirekte tale: like → liked, og 'I' bliver til 'she'."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'I enjoy ___ books.'","o":["to read","read","reads","reading"],"a":"reading","r":"Efter 'enjoy' bruger man -ing: I enjoy reading."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'I want ___ a doctor.'","o":["becoming","become","to become","became"],"a":"to become","r":"Efter 'want' bruger man 'to' + verbum: I want to become …"},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'She stopped ___ when the teacher came in.'","o":["to talk","talking","talk","talked"],"a":"talking","r":"'Stop + -ing' = holde op med at gøre noget."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'He is used to ___ up early.'","o":["getting","get","got","gets"],"a":"getting","r":"'Be used to + -ing' = være vant til at."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'Neither of my parents ___ coffee.'","o":["drink","are drinking","drinking","drinks"],"a":"drinks","r":"'Neither of' tæller som ental: Neither of them drinks …"},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'I wish I ___ fly.'","o":["can","will","could","am"],"a":"could","r":"Efter 'I wish' bruger man datid: I wish I could fly = gid jeg kunne flyve."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'You'd better ___ now, or you'll miss the bus.'","o":["to leave","leave","leaving","left"],"a":"leave","r":"'You'd better' + grundform = du må hellere: You'd better leave."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'The town ___ I was born is very small.'","o":["where","which","who","what"],"a":"where","r":"'Where' bruges om steder: the town where I was born."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'By the time we arrived, the film ___ already started.'","o":["has","was","did","had"],"a":"had","r":"Førnutid (had + 3. form) bruges om noget, der skete før noget andet i fortiden."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'I'll call you as soon as I ___ home.'","o":["will get","got","get","getting"],"a":"get","r":"Efter 'as soon as' om fremtiden bruger man nutid: as soon as I get home."},
{"g":5,"b":4,"k":"g","q":"Hvilken sætning med 'each' er rigtig?","o":["Each of the pupils have a book.","Each of the pupils has a book.","Each of the pupil has books.","Each the pupils has a book."],"a":"Each of the pupils has a book.","r":"'Each' tæller som ental: Each of the pupils has …"},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'He's the boy ___ father is a pilot.'","o":["whose","who's","who","which"],"a":"whose","r":"'Whose' = hvis. 'Who's' er en forkortelse af 'who is'."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'It's ___ cold that we can't go outside.'","o":["such","too","very","so"],"a":"so","r":"'So … that' = så … at: so cold that we can't go out."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'It was ___ a good film that I watched it twice.'","o":["so","too","such","very"],"a":"such","r":"'Such a + navneord' = sådan en: such a good film."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'This box is too heavy ___ me to carry.'","o":["to","for","of","at"],"a":"for","r":"'Too heavy for me to carry' = for tung for mig at bære."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'run out of'?","o":["løbe tør for","løbe ud af","løbe fra","løbe efter"],"a":"løbe tør for","r":"'Run out of' betyder løbe tør for: We ran out of bread."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'put off' i 'Don't put off your homework'?","o":["tage af","slukke","smide ud","udsætte"],"a":"udsætte","r":"'Put off' betyder udsætte. 'Don't put it off' = lad være med at udsætte det."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'get on with' i 'I get on well with my sister'?","o":["komme ind i","stige på","komme godt ud af det med","komme videre fra"],"a":"komme godt ud af det med","r":"'Get on well with someone' = komme godt ud af det med nogen."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'come up with'?","o":["komme op med elevatoren","finde på","komme sammen med","kaste op"],"a":"finde på","r":"'Come up with an idea' = finde på en idé."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'make up' i 'make up a story'?","o":["digte","sminke","vågne","samle op"],"a":"digte","r":"'Make up a story' = finde på/digte en historie. 'Make-up' er også sminke."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'take after' i 'She takes after her mother'?","o":["tager efter","følger efter","passer på","ligner"],"a":"ligner","r":"'Take after someone' = ligne nogen (i familien)."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'set off'?","o":["sætte ned","slukke","tage af sted","stille op"],"a":"tage af sted","r":"'Set off' betyder tage af sted på en rejse."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'bring up' i 'She was brought up in Aarhus'?","o":["bragt op ad trappen","opdraget/vokset op","nævnt","hentet"],"a":"opdraget/vokset op","r":"'Be brought up' = blive opdraget/vokse op."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'disappointed'?","o":["skuffet","forsvundet","uenig","udnævnt"],"a":"skuffet","r":"'Disappointed' betyder skuffet."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'embarrassed'?","o":["gravid","omfavnet","indelukket","flov"],"a":"flov","r":"'Embarrassed' betyder flov eller pinlig berørt. Pas på: det betyder ikke gravid!"},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'jealous'?","o":["glad","lysten","jaloux","nysgerrig"],"a":"jaloux","r":"'Jealous' betyder jaloux eller misundelig."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'confused'?","o":["overbevist","forvirret","tilfreds","forkølet"],"a":"forvirret","r":"'Confused' betyder forvirret."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'curious'?","o":["nysgerrig","kunstig","kurv","kurér"],"a":"nysgerrig","r":"'Curious' betyder nysgerrig. Det kan også betyde mærkelig."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'reliable'?","o":["realistisk","religiøs","lettet","pålidelig"],"a":"pålidelig","r":"'Reliable' betyder pålidelig: én, man kan stole på."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'generous'?","o":["generel","genert","gavmild","genial"],"a":"gavmild","r":"'Generous' betyder gavmild."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'challenge'?","o":["chance","udfordring","mester","valg"],"a":"udfordring","r":"'Challenge' betyder udfordring."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'advice'?","o":["råd","reklame","eventyr","advarsel"],"a":"råd","r":"'Advice' betyder råd: 'Can you give me some advice?' Det tælles ikke: man siger ikke 'an advice'."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'knowledge'?","o":["kniv","knogle","nødvendighed","viden"],"a":"viden","r":"'Knowledge' betyder viden. Det kommer af 'know' — vide."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'thought' som navneord?","o":["tråd","tærte","tanke","tæer"],"a":"tanke","r":"'Thought' er en tanke. Det er også datid af 'think'."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'though' i 'It was cold, though'?","o":["derfor","dog/alligevel","gennem","tanke"],"a":"dog/alligevel","r":"'Though' i slutningen af en sætning betyder dog eller alligevel."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'through'?","o":["gennem","selvom","tre","tanke"],"a":"gennem","r":"'Through' betyder gennem: through the forest = gennem skoven."},
{"g":5,"b":4,"k":"o","q":"Hvad er det modsatte af 'agree'?","o":["unagree","inagree","misagree","disagree"],"a":"disagree","r":"'Disagree' betyder være uenig."},
{"g":5,"b":4,"k":"o","q":"Hvad er det modsatte af 'patient' (tålmodig)?","o":["unpatient","dispatient","impatient","inpatient"],"a":"impatient","r":"'Impatient' betyder utålmodig."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'unbelievable'?","o":["usynlig","utrolig","uundgåelig","uheldig"],"a":"utrolig","r":"Un- (ikke) + believe (tro) + -able (kan) = kan ikke tros — utrolig."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'misunderstand'?","o":["misforstå","savne forståelse","forstå godt","undervise"],"a":"misforstå","r":"Mis- betyder forkert: misunderstand = misforstå."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'He let the cat out of the bag'?","o":["Han lukkede katten ud","Han købte en kat","Han blev bange for katten","Han afslørede hemmeligheden"],"a":"Han afslørede hemmeligheden","r":"Idiom! 'Let the cat out of the bag' = afsløre en hemmelighed."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'We're in the same boat'?","o":["Vi sejler sammen","Vi har en båd","Vi er i samme situation","Vi er uvenner"],"a":"Vi er i samme situation","r":"Idiom! 'In the same boat' = i samme båd/situation — ligesom på dansk."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'It costs an arm and a leg'?","o":["Det gør ondt","Det er meget dyrt","Det er billigt","Det er farligt"],"a":"Det er meget dyrt","r":"Idiom! 'Cost an arm and a leg' = koste det hvide ud af øjnene."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'Don't judge a book by its cover'?","o":["Døm ikke ud fra udseendet","Læs ikke bøger med grimme forsider","Køb kun pæne bøger","Pas på dine bøger"],"a":"Døm ikke ud fra udseendet","r":"Idiom! Man skal ikke dømme noget eller nogen ud fra udseendet."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'Hit the books'?","o":["Slå på bøgerne","Smide bøgerne","Sælge bøgerne","Gå i gang med at læse lektier"],"a":"Gå i gang med at læse lektier","r":"Idiom! 'Hit the books' = gå i gang med at studere."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'I'm over the moon'?","o":["Jeg er i rummet","Jeg er meget træt","Jeg er helt oppe at køre af glæde","Jeg er forvirret"],"a":"Jeg er helt oppe at køre af glæde","r":"Idiom! 'Over the moon' = himmelhenrykt."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'It's on the tip of my tongue'?","o":["Jeg har brændt tungen","Jeg kan næsten huske det","Jeg vil ikke sige det","Det smager godt"],"a":"Jeg kan næsten huske det","r":"Idiom! 'On the tip of my tongue' = jeg har det lige på tungen."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'Actions speak louder than words'?","o":["Handling betyder mere end ord","Man skal råbe højt","Ord er vigtigere end handling","Man skal være stille"],"a":"Handling betyder mere end ord","r":"Ordsprog: Det, man gør, betyder mere end det, man siger."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'Could you do me a favour?'","o":["Kan du lide mig?","Kan du give mig en gave?","Kan du gøre det for sjov?","Kan du gøre mig en tjeneste?"],"a":"Kan du gøre mig en tjeneste?","r":"'Do someone a favour' = gøre nogen en tjeneste."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'I'd rather not'?","o":["Det vil jeg rigtig gerne","Det har jeg gjort","Det vil jeg helst ikke","Det ved jeg ikke"],"a":"Det vil jeg helst ikke","r":"'I'd rather not' er en høflig måde at sige nej på."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Despite being the smallest player on the team, Jamie scored the winning goal.' Hvad er overraskende?","o":["At holdet tabte","At den mindste spiller scorede sejrsmålet","At Jamie er den største","At der ikke blev scoret"],"a":"At den mindste spiller scorede sejrsmålet","r":"'Despite' = på trods af. Det er overraskende, fordi han er den mindste."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Had I known about the party, I would have come.' Hvad betyder det?","o":["Personen vidste ikke noget om festen","Personen var til festen","Personen ville ikke med","Festen blev aflyst"],"a":"Personen vidste ikke noget om festen","r":"'Had I known' = hvis jeg havde vidst. Personen vidste det altså ikke."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The village, which is surrounded by mountains, can only be reached by train.' Hvordan kommer man til landsbyen?","o":["med bil eller tog","kun til fods","med fly","kun med tog"],"a":"kun med tog","r":"'Can only be reached by train' = man kan kun komme dertil med tog."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Not only did Mia win the race, she also broke the school record.' Hvad gjorde Mia?","o":["Hun vandt, men faldt","Hun tabte løbet","Hun vandt og slog skolens rekord","Hun slog sig"],"a":"Hun vandt og slog skolens rekord","r":"'Not only … but also' = ikke kun … men også."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The museum is usually packed, but on Monday mornings it's almost empty.' Hvornår er der færrest besøgende?","o":["i weekenden","mandag morgen","hver eftermiddag","altid"],"a":"mandag morgen","r":"'Almost empty' = næsten tomt. Det er mandag morgen."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Leo pretended to be asleep when his mum came in.' Sov Leo?","o":["Nej, han lod som om","Ja, han sov tungt","Ja, men han vågnede","Det står der ikke"],"a":"Nej, han lod som om","r":"'Pretended' betyder lod som om."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Unless it stops raining, the trip will be cancelled.' Hvad skal der til, for at turen bliver til noget?","o":["Det skal begynde at regne","Der skal komme flere med","Bussen skal komme","Det skal holde op med at regne"],"a":"Det skal holde op med at regne","r":"'Unless' betyder medmindre."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Freya was the last to leave, so she turned off the lights.' Hvorfor slukkede Freya lyset?","o":["Hun var bange","Lyset var i stykker","Hun gik som den sidste","Hun ville sove"],"a":"Hun gik som den sidste","r":"'The last to leave' = den sidste, der gik."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The teacher told us to hand in our essays by Friday at the latest.' Hvornår skal stilen afleveres?","o":["tidligst fredag","senest fredag","præcis fredag kl. 8","efter fredag"],"a":"senest fredag","r":"'At the latest' betyder senest."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Hardly had we sat down when the fire alarm went off.' Hvad skete der?","o":["Brandalarmen gik lige efter, de havde sat sig","De sad længe, før alarmen gik","Alarmen gik ikke","De satte sig efter alarmen"],"a":"Brandalarmen gik lige efter, de havde sat sig","r":"'Hardly … when' = knap havde de … før."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Most people think the old house is haunted, but Sam doesn't believe in ghosts.' Hvad mener Sam?","o":["Han tror, der spøger","Han er bange for huset","Han bor i huset","Han tror ikke, der spøger"],"a":"Han tror ikke, der spøger","r":"'Haunted' = hjemsøgt. Sam tror ikke på spøgelser (ghosts)."},
{"g":5,"b":4,"k":"l","q":"Læs: 'It was such a long walk that by the end, our feet were killing us.' Hvordan havde deres fødder det?","o":["De var kolde","De var våde","De gjorde meget ondt","De var fine"],"a":"De gjorde meget ondt","r":"'My feet are killing me' er et udtryk for, at fødderne gør meget ondt."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The shop gave Mark a refund because the headphones were broken.' Hvad fik Mark?","o":["nye høretelefoner gratis","pengene tilbage","en rabat på næste køb","en undskyldning"],"a":"pengene tilbage","r":"'Refund' betyder at få pengene tilbage."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Even though Ella studied all night, she found the test really hard.' Hvordan var prøven for Ella?","o":["svær","nem","kedelig","kort"],"a":"svær","r":"'Even though' = selvom. Hun syntes, prøven var svær (hard)."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The bridge has been closed for repairs since March.' Hvad ved vi om broen?","o":["Den åbnede i marts","Den blev bygget i marts","Den er åben nu","Den har været lukket siden marts"],"a":"Den har været lukket siden marts","r":"'Has been closed … since March' = har været lukket siden marts."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Jack is always the first to volunteer when somebody needs help.' Hvordan er Jack?","o":["doven","genert","hjælpsom","uhøflig"],"a":"hjælpsom","r":"'Volunteer' betyder melde sig frivilligt. Jack er hjælpsom."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Our flight was delayed, which meant we missed our connecting flight.' Hvad var følgen af forsinkelsen?","o":["De kom for tidligt","De nåede ikke deres næste fly","De fik et bedre fly","Flyet blev aflyst"],"a":"De nåede ikke deres næste fly","r":"'Missed our connecting flight' = nåede ikke vores videre fly."},
{"g":5,"b":4,"k":"l","q":"Læs: 'Ida's room is spotless.' Hvordan er Idas værelse?","o":["helt rent","meget rodet","fuld af prikker","meget mørkt"],"a":"helt rent","r":"'Spotless' betyder pletfri — helt rent."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'If it hadn't rained, we ___ gone to the beach.'","o":["will have","would","had","would have"],"a":"would have","r":"Tredje betingelse (noget, der ikke skete): If + had …, … would have + 3. form."},
{"g":5,"b":4,"k":"g","q":"Hvilket ord mangler? 'She asked me where I ___.'","o":["live","do live","lived","living"],"a":"lived","r":"I indirekte spørgsmål rykker tiden tilbage, og der er ingen 'do': She asked me where I lived."},
{"g":5,"b":4,"k":"o","q":"Hvad betyder 'look up' i 'Look up the word in a dictionary'?","o":["kigge op i luften","slå op","se op til","lede efter i huset"],"a":"slå op","r":"'Look up a word' = slå et ord op."},
{"g":5,"b":4,"k":"h","q":"Hvad betyder 'Easier said than done'?","o":["Lettere sagt end gjort","Sig det hurtigt","Det er gjort nu","Det er nemt at gøre"],"a":"Lettere sagt end gjort","r":"Udtrykket betyder, at noget er nemt at sige, men svært at gøre."},
{"g":5,"b":4,"k":"l","q":"Læs: 'The more Tom thought about the problem, the more confused he became.' Hvad skete der med Tom?","o":["Han løste problemet","Han holdt op med at tænke","Han blev gladere","Han blev mere og mere forvirret"],"a":"Han blev mere og mere forvirret","r":"'The more … the more confused' = jo mere … jo mere forvirret."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
